// npm run feedback -- up|down ["optional comment"]
// Attaches a thumbs up / down to the last post generated by `npm run run`, as a Langfuse score.
// In a real app this is the 👍 / 👎 button under the generated post.
import { parseArgs } from "node:util";
import { LangfuseClient } from "@langfuse/client";
import { loadLastTrace, saveLastTrace } from "../last-trace.js";

const { positionals } = parseArgs({ allowPositionals: true });
const [vote, comment] = positionals;

if (vote !== "up" && vote !== "down") {
  console.error('Usage: npm run feedback -- up|down ["optional comment"]');
  process.exit(1);
}

const langfuse = new LangfuseClient();

try {
  const last = await loadLastTrace();
  const timestamp = last.feedbackTimestamp ?? new Date().toISOString();

  langfuse.score.create({
    id: `${last.traceId}-user-feedback`, // one feedback score per trace
    timestamp,
    traceId: last.traceId,
    name: "user-feedback",
    value: vote === "up" ? 1 : 0,
    dataType: "BOOLEAN",
    comment,
    metadata: { source: "cli" },
  });
  await langfuse.flush(); // scores are batched: send now, the process is about to exit

  await saveLastTrace({ ...last, feedbackTimestamp: timestamp });
  const changed = last.feedbackTimestamp ? " (vote updated)" : "";
  console.log(`${vote === "up" ? "👍" : "👎"} saved on the post for ${last.url}${changed}`);
  console.log(`Trace: ${await langfuse.getTraceUrl(last.traceId)}`);
} catch (error) {
  console.error(`✖ ${error instanceof Error ? error.message : error}`);
  process.exitCode = 1;
}
